function updateBoxSim() {
    const a = parseInt(document.getElementById('input-box-a').value, 10);
    const b = parseInt(document.getElementById('input-box-b').value, 10);

    document.getElementById('badge-box-a').innerText = (a >= 0 ? '+' : '') + a;
    document.getElementById('badge-box-b').innerText = (b >= 0 ? '+' : '') + b;

    document.getElementById('head-a').innerText = (a >= 0 ? '+' : '') + a;
    document.getElementById('head-b').innerText = (b >= 0 ? '+' : '') + b;

    document.getElementById('cell-ax').innerText = (a >= 0 ? '+' : '') + a + 'x';
    document.getElementById('cell-bx').innerText = (b >= 0 ? '+' : '') + b + 'x';

    const ab = a * b;
    document.getElementById('cell-ab').innerText = (ab >= 0 ? '+' : '') + ab;

    const mid = a + b;
    let midStr = '';
    if (mid > 0) midStr = `+ ${mid}x`;
    else if (mid < 0) midStr = `- ${Math.abs(mid)}x`;

    let constStr = '';
    if (ab > 0) constStr = `+ ${ab}`;
    else if (ab < 0) constStr = `- ${Math.abs(ab)}`;

    document.getElementById('box-result-poly').innerText = `x² ${midStr} ${constStr}`.trim();
}

document.addEventListener('DOMContentLoaded', () => {
    updateBoxSim();
});
